def _find_pacification_target(self, content, name: str) -> Optional[str]:
    """Resolve living canonical 内乱 leader still needing 自新受抚 (敌对/潜伏 only)."""
    matched = None
    if name in content.characters:
        matched = name
    else:
        matched = next((
            key for key, character in content.characters.items()
            if name in (character.aliases or [])
        ), None)
    if not matched:
        return None
    row = self.conn.execute(
        "SELECT status, power_id FROM characters WHERE name=?", (matched,),
    ).fetchone()
    if row is None or row["status"] != "active" or row["power_id"] in (None, "ming"):
        return None
    power = self.conn.execute(
        "SELECT kind, leader, stance FROM powers WHERE id=?", (row["power_id"],),
    ).fetchone()
    if power is None or not (
        power["kind"] == "内乱"
        and power["stance"] in {"敌对", "潜伏"}
        and power["leader"] == matched
    ):
        return None
    return matched

def _strip_controlled_namespace(text: str, namespace: str) -> str:
    """Strip only the extractor's exact namespace wrappers, never prose."""
    if text.startswith("@"):
        return text[1:]
    prefix = f"{namespace}."
    if text.startswith(prefix):
        return text[len(prefix):]
    return text

def _apply_recovery_driven_transfers(
    db: GameDB,
    state: GameState,
    *,
    commit: bool = True,
) -> Tuple[List[Dict[str, object]], List[Dict[str, object]]]:
    """#652/0087：赈济/招抚屯田回流单核（确定性；LLM 零产回流）。

    触发：带 recovery 身份的 grant_allocation（赈灾/招抚屯田）+ 属地 region +
    本回合已付代价 + 已落结构化执行判决。基线=实抵万两×RECOVERY_PERSONS_PER_WAN，
    再经执行 outcome 成色折减；经 _apply_population_transfers reason=回流 唯一落库。
    幂等键 (dossier_id, turn)：同键不双扣池。立即开仓/#522 pacification 不在此列。
    """
    if db.population_unit != POPULATION_UNIT_PERSONS:
        return [], []
    turn = int(state.turn)
    # 月份推进事务只执行一次；同一案在本次扫描内仅回流一次。
    seen_keys: set[tuple[int, int]] = set()

    records: List[Dict[str, object]] = []
    remaining_by_region: Dict[str, int] = {}
    rows = db.conn.execute(
        """
        SELECT id, status, target_kind, target_id, payload_json,
               execution_outcome, closed_turn
        FROM decree_dossiers
        WHERE action_type='grant_allocation'
        ORDER BY id
        """
    ).fetchall()
    for row in rows:
        dossier_id = int(row["id"])
        if (dossier_id, turn) in seen_keys:
            continue
        try:
            payload = json.loads(str(row["payload_json"] or "{}"))
        except (TypeError, ValueError):
            continue
        if not isinstance(payload, dict):
            continue
        grant_action = str(payload.get("grant_action") or "").strip()
        if grant_action not in RECOVERY_GRANT_ACTIONS:
            continue
        target_kind = str(row["target_kind"] or payload.get("target_kind") or "").strip()
        region_id = str(row["target_id"] or payload.get("target_id") or "").strip()
        if target_kind != "region" or not region_id:
            continue
        if db.conn.execute("SELECT 1 FROM regions WHERE id=?", (region_id,)).fetchone() is None:
            continue
        outcome = str(row["execution_outcome"] or "").strip()
        if outcome not in RECOVERY_OUTCOME_FACTORS:
            continue
        cadence = str(payload.get("cadence") or "").strip()
        closed_turn = int(row["closed_turn"] or 0)
        if cadence != "每月" and closed_turn != turn:
            continue
        factor = float(RECOVERY_OUTCOME_FACTORS[outcome])
        if factor <= 0:
            seen_keys.add((dossier_id, turn))
            continue
        if cadence == "每月":
            reconciled = [
                int(item["arrived_amount"])
                for item in db.list_dossier_reconciliations(dossier_id)
                if int(item.get("turn") or 0) == turn
            ]
            if reconciled:
                silver = max(0, sum(reconciled))
            else:
                paid_row = db.conn.execute(
                    "SELECT COALESCE(SUM(-delta), 0) FROM economy_ledger "
                    "WHERE origin_ref=? AND turn=? AND delta<0",
                    (f"dossier:{dossier_id}", turn),
                ).fetchone()
                silver = max(0, int(paid_row[0] or 0))
        else:
            silver = _recovery_effective_silver_wan(db, dossier_id, turn)
        if silver <= 0:
            continue
        raw_persons = silver * RECOVERY_PERSONS_PER_WAN * factor
        amount = int(round(raw_persons))

def get_rescript_desk_rows_by_keys(
    self, keys: Sequence[str],
) -> List[Dict[str, object]]:
    """按 decision_key 取 desk 行（含 decided）——C1.1 崩溃重入 already_applied 用。"""
    out: List[Dict[str, object]] = []
    seen: set[str] = set()
    for raw in keys:
        key = str(raw or "").strip()
        if not key or key in seen:
            continue
        parts = key.split(":")
        if len(parts) != 3:
            continue
        kind, turn_s, idx_s = parts
        try:
            turn_i, idx_i = int(turn_s), int(idx_s)
        except (TypeError, ValueError):
            continue
        if kind not in {"rescript_draft", "decision"}:
            continue
        r = self.conn.execute(
            """
            SELECT *
            FROM pending_decisions
            WHERE turn = ? AND idx = ? AND kind = ?
            """,
            (turn_i, idx_i, kind),
        ).fetchone()
        if r is None:
            continue
        seen.add(key)
        out.append(self._project_rescript_desk_row(r))
    return out

def _choose_rescripts(
    db: GameDB, turn: int, hostile: int, vital: int, appointment: int,
) -> list[dict]:
    """Persist choices exactly as the normal session boundary does, then phase2 owns them."""
    chosen = []
    for decision in db.list_pending_decisions(turn):
        options = decision["options"]
        if decision["event_id"] == f"dossier:{hostile}":
            choice = next(row for row in options if row.get("dossier_decision") == "hold")
        elif decision["event_id"] in {f"dossier:{vital}", f"dossier:{appointment}"}:
            choice = next(row for row in options if row.get("dossier_decision") == "withdrawn")
        else:
            # authority_edge and any other reject: explicit non-force via dossier_decision.
            # Never fall through to options[0] (force_promulgated on ordinary rejects).
            choice = next(
                row for row in options
                if row.get("dossier_decision") in {"withdrawn", "hold"}
            )
        db.conn.execute(
            "UPDATE pending_decisions SET choice_json=?,status='chosen' WHERE turn=? AND idx=?",
            (json.dumps(choice, ensure_ascii=False), int(turn), int(decision["idx"])),
        )
        chosen.append({"event_id": decision["event_id"], "choice": choice})
    db.conn.commit()
    return chosen

def _promulgation_decision_raw(row: dict) -> str:
    """Resolve the current promulgation-slot raw enum for a dossier row."""
