def overlay_power_delta(power_id: object, raw_changes: object) -> None:
    pid = str(power_id or "").strip()
    if not pid or not isinstance(raw_changes, dict):
        return
    row = power_row(pid)
    if row is None:
        return
    for raw_field, value in raw_changes.items():
        field = POWER_FIELD_ALIASES.get(str(raw_field).strip(), str(raw_field).strip())
        if field in {"reason", "last_action"}:
            continue
        if field not in _PENDING_POWER_GATE_FIELDS:
            continue
        try:
            if isinstance(value, bool) or isinstance(value, float):
                raise ValueError("非整数 delta")
            delta = int(value)
        except (TypeError, ValueError):
            continue
        old_value = int(row[field])
        new_value = max(0, min(100, old_value + delta))
        if new_value == old_value:
            continue
        row[field] = new_value
        pending_power_fields.setdefault(pid, {})[field] = new_value

def _decree_ref_is_secret(db: Any, decree_ref: str) -> bool:
    from ming_sim.materials import is_secret_order_origin

    if is_secret_order_origin(decree_ref):
        return True
    prefix = "pending-action:"
    if not str(decree_ref).startswith(prefix):
        return False
    raw = str(decree_ref)[len(prefix):].split(":", 1)[0]
    if not raw.isdigit() or not hasattr(db, "conn"):
        return False
    row = db.conn.execute(
        "SELECT kind FROM pending_actions WHERE id=?", (int(raw),),
    ).fetchone()
    return row is not None and str(row["kind"] or "") == "secret_order"

