def _scan_outside_strings(text: str, handle) -> str:
    """逐字扫描 text，字符串内部（含转义）原样输出；字符串外的字符交给
    handle(text, i, out, n) -> next_i 处理（append 想保留的到 out、返回下一位置）。
    JSONC 清洗的共享底座：字符串/转义态只在此一处维护，避免每趟各写一份状态机。"""
    out: List[str] = []
    in_str = esc = False
    i, n = 0, len(text)
    while i < n:
        ch = text[i]
        if in_str:
            out.append(ch)
            if esc:
                esc = False
            elif ch == "\\":
                esc = True
            elif ch == '"':
                in_str = False
            i += 1
        elif ch == '"':
            in_str = True
            out.append(ch)
            i += 1
        else:
            i = handle(text, i, out, n)
    return "".join(out)

